162	// RegisterProduct 登记产品：购买时刻、保修天数和除外故障代码。
163	// 编号重复时返回 ErrDuplicateID 且保留原记录；已存在的非空编号优先于其他
164	// 参数校验，即使新提交的保修天数、截止时刻或除外清单不合法也报编号重复，
165	// 原记录不被覆盖、清空或部分替换。保修天数必须为正整数，且自购买时刻起完整
166	// 天数（每天二十四小时）的截止时刻必须落在时间类型的可表示范围内，否则返回
167	// ErrInvalidParam，不保存产品记录。
168	func (s *Store) RegisterProduct(id string, purchaseTime time.Time, warrantyDays int, excludedCodes []string) error {
169		if id == "" {
170			return fmt.Errorf("%w: product id must not be empty", ErrInvalidParam)
171		}
172		s.mu.Lock()
173		defer s.mu.Unlock()
174		// 编号已存在时一律报重复并保留原记录，不再校验新提交的条款。
175		if _, ok := s.products[id]; ok {
176			return fmt.Errorf("%w: product %q", ErrDuplicateID, id)
177		}
178		if warrantyDays <= 0 {
179			return fmt.Errorf("%w: warranty days must be a positive integer", ErrInvalidParam)
180		}
181		// 截止时刻超出时间类型可表示范围的期限无法登记，不保存产品记录；
182		// 之后以同一编号提交可表示的条款仍可正常登记。
183		if _, ok := warrantyExpiry(purchaseTime, warrantyDays); !ok {
184			return fmt.Errorf("%w: warranty expiry for %d days is not representable", ErrInvalidParam, warrantyDays)
185		}
186		codes := make(map[string]struct{}, len(excludedCodes))
187		for _, c := range excludedCodes {
188			if c == "" {
189				return fmt.Errorf("%w: excluded fault code must not be empty", ErrInvalidParam)
190			}
191			codes[c] = struct{}{}
192		}
193		s.products[id] = &Product{
194			ID:            id,
195			PurchaseTime:  purchaseTime,
196			WarrantyDays:  warrantyDays,
197			ExcludedCodes: codes,
198		}
199		return nil
200	}
