202	// RegisterPart 登记备件及其非负整数初始库存。
203	// 编号重复时返回 ErrDuplicateID 且保留原记录。
204	func (s *Store) RegisterPart(id string, initialStock int) error {
205		if id == "" {
206			return fmt.Errorf("%w: part id must not be empty", ErrInvalidParam)
207		}
208		if initialStock < 0 {
209			return fmt.Errorf("%w: initial stock must be a non-negative integer", ErrInvalidParam)
210		}
