212		defer s.mu.Unlock()
213		if _, ok := s.parts[id]; ok {
214			return fmt.Errorf("%w: part %q", ErrDuplicateID, id)
215		}
216		s.parts[id] = &Part{ID: id, Stock: initialStock}
217		return nil
218	}
219	
220	// SubmitRequest 提交保修请求，指定产品和故障代码。
221	// 编号重复时返回 ErrDuplicateID 且保留原记录。
222	func (s *Store) SubmitRequest(id, productID, faultCode string) error {
223		if id == "" {
224			return fmt.Errorf("%w: request id must not be empty", ErrInvalidParam)
225		}
226		if faultCode == "" {
227			return fmt.Errorf("%w: fault code must not be empty", ErrInvalidParam)
228		}
229		s.mu.Lock()
230		defer s.mu.Unlock()
231		if _, ok := s.requests[id]; ok {
232			return fmt.Errorf("%w: request %q", ErrDuplicateID, id)
233		}
234		s.requests[id] = &Request{ID: id, ProductID: productID, FaultCode: faultCode}
235		return nil
236	}
237	
238	// Product 返回指定编号的产品副本，不存在时返回 ErrNotFound。
239	func (s *Store) Product(id string) (Product, error) {
240		s.mu.Lock()
241		defer s.mu.Unlock()
242		p, ok := s.products[id]
243		if !ok {
244			return Product{}, fmt.Errorf("%w: product %q", ErrNotFound, id)
245		}
246		cp := *p
247		cp.ExcludedCodes = make(map[string]struct{}, len(p.ExcludedCodes))
248		for k := range p.ExcludedCodes {
249			cp.ExcludedCodes[k] = struct{}{}
250		}
251		return cp, nil
252	}
253	
254	// Part 返回指定编号的备件副本，不存在时返回 ErrNotFound。
255	func (s *Store) Part(id string) (Part, error) {
256		s.mu.Lock()
257		defer s.mu.Unlock()
258		p, ok := s.parts[id]
259		if !ok {
260			return Part{}, fmt.Errorf("%w: part %q", ErrNotFound, id)
261		}
262		return *p, nil
263	}
264	
265	// Request 返回指定编号的请求副本，不存在时返回 ErrNotFound。
266	func (s *Store) Request(id string) (Request, error) {
267		s.mu.Lock()
268		defer s.mu.Unlock()
269		r, ok := s.requests[id]
270		if !ok {
271			return Request{}, fmt.Errorf("%w: request %q", ErrNotFound, id)
272		}
273		return *r, nil
274	}
