185		}
186		if _, err := s.Reserve("cA2", "rA", "part1", 2, t0.Add(50*day), nowOK); err != nil {
187			t.Fatalf("reserve cA2: %v", err)
188		}
189		if _, err := s.Reserve("cB4", "rB", "part1", 4, t0.Add(30*day), nowOK); err != nil {
190			t.Fatalf("reserve cB4: %v", err)
191		}
192		if _, err := s.Use("uA-used", "cA5", 2, nowOK); err != nil {
193			t.Fatalf("use 2 from cA5: %v", err)
194		}
195		if _, err := s.Cancel("cA5", nowOK); err != nil {
196			t.Fatalf("cancel cA5: %v", err)
197		}
198		// 取消后：实物 10，有效占用 6，可承诺 4。
199		assertPartAccount(t, s, 10, 6, 4)
200	
201		// 新请求在晚于取消的操作时刻预留释放后的全部 4 件：成功。
202		later := t0.Add(11 * day)
203		cC4, err := s.Reserve("cC4", "rC", "part1", 4, t0.Add(35*day), later)
204		if err != nil {
205			t.Fatalf("reserve freed 4 for rC: %v", err)
206		}
207		if cC4.Quantity != 4 || cC4.Used != 0 || cC4.RequestID != "rC" || cC4.Canceled || cC4.Expired {
208			t.Fatalf("new commitment for rC: %+v", cC4)
209		}
210		// 实物仍为 10，有效占用变为 10（2+4+4），可承诺为 0。
211		st, err := s.PartStatus("part1", later)
212		if err != nil {
213			t.Fatalf("part status: %v", err)
214		}
215		if st.PhysicalRemaining != 10 || st.ActiveOccupied != 10 || st.Committable != 0 {
216			t.Fatalf("stock after freed quantity re-reserved: phys=%d occupied=%d committable=%d",
217				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
218		}
219		// 可承诺确认为 0：再要 1 件的新合格请求无法预留。
220		if _, err := s.Reserve("cC-extra", "rC", "part1", 1, t0.Add(35*day), later); !errors.Is(err, ErrInsufficientStock) {
221			t.Fatalf("reserve beyond zero committable: got %v, want ErrInsufficientStock", err)
222		}
223	
224		// 再次取消原来的 5 件承诺：正常返回已取消结果，但不能再次释放 3 件。
225		again, err := s.Cancel("cA5", later)
226		if err != nil {
227			t.Fatalf("repeat cancel cA5: %v", err)
228		}
229		if !again.Canceled || again.Quantity != 5 || again.Used != 2 || again.Unused() != 3 {
230			t.Fatalf("repeat cancel result: %+v", again)
231		}
232		st2, err := s.PartStatus("part1", later)
233		if err != nil {
234			t.Fatalf("part status after repeat cancel: %v", err)
235		}
236		if st2.PhysicalRemaining != 10 || st2.ActiveOccupied != 10 || st2.Committable != 0 {
237			t.Fatalf("repeat cancel changed stock: phys=%d occupied=%d committable=%d",
238				st2.PhysicalRemaining, st2.ActiveOccupied, st2.Committable)
239		}
240	
241		// 对原承诺用新的使用编号提交 1 件使用：返回 ErrCommitmentClosed。
242		if _, err := s.Use("uA-after-cancel", "cA5", 1, later); !errors.Is(err, ErrCommitmentClosed) {
243			t.Fatalf("new usage on canceled commitment: got %v, want ErrCommitmentClosed", err)
244		}
245	
246		// 实物库存与各笔已用数量保持原值。
247		st3, err := s.PartStatus("part1", later)
248		if err != nil {
249			t.Fatalf("part status after rejected usage: %v", err)
250		}
251		if st3.PhysicalRemaining != 10 || st3.ActiveOccupied != 10 || st3.Committable != 0 {
252			t.Fatalf("rejected usage changed stock: phys=%d occupied=%d committable=%d",
253				st3.PhysicalRemaining, st3.ActiveOccupied, st3.Committable)
254		}
255		cA5, _ := s.Commitment("cA5")
256		if cA5.Used != 2 || !cA5.Canceled {
257			t.Fatalf("cA5 after rejected usage: %+v", cA5)
258		}
259		for _, tc := range []struct {
260			id   string
261			want Commitment
262		}{
263			{"cA2", Commitment{ID: "cA2", RequestID: "rA", PartID: "part1", Quantity: 2, Used: 0}},
264			{"cB4", Commitment{ID: "cB4", RequestID: "rB", PartID: "part1", Quantity: 4, Used: 0}},
265			{"cC4", Commitment{ID: "cC4", RequestID: "rC", PartID: "part1", Quantity: 4, Used: 0}},
266		} {
267			c, err := s.Commitment(tc.id)
268			if err != nil {
